(function() {
  window.CardSpoke.registerPlugin('card-search-highlight', {
    manifest: {
      name: 'Card Search Highlight',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'In-page search overlay with match navigation',
      layer: 'feature',
      permissions: ['ui-override']
    },
    setup: async function(ctx) {
      var self = this;
      var matches = [];
      var currentMatch = -1;
      var overlay = document.createElement('div');
      overlay.className = 'search-highlight-overlay hidden';
      overlay.innerHTML = '<input class="search-highlight-input" type="text" placeholder="Search cards...">' +
        '<span class="search-highlight-info">0 / 0</span>' +
        '<button class="search-highlight-btn" data-dir="prev">Prev</button>' +
        '<button class="search-highlight-btn" data-dir="next">Next</button>' +
        '<button class="search-highlight-close">&times;</button>';
      document.body.appendChild(overlay);
      var input = overlay.querySelector('.search-highlight-input');
      var info = overlay.querySelector('.search-highlight-info');
      var prevBtn = overlay.querySelector('[data-dir="prev"]');
      var nextBtn = overlay.querySelector('[data-dir="next"]');
      var closeBtn = overlay.querySelector('.search-highlight-close');
      function clearHighlights() {
        var marks = document.querySelectorAll('mark.search-match, mark.search-match-active');
        marks.forEach(function(m) {
          var parent = m.parentNode;
          parent.replaceChild(document.createTextNode(m.textContent), m);
          parent.normalize();
        });
        matches = [];
        currentMatch = -1;
      }
      function highlightText(query) {
        clearHighlights();
        if (!query || query.length < 2) {
          info.textContent = '0 / 0';
          return;
        }
        var containers = document.querySelectorAll('.card-item, .card-detail, .card-detail-body, .card-title');
        containers.forEach(function(container) {
          var walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT, null, false);
          var textNodes = [];
          while (walker.nextNode()) textNodes.push(walker.currentNode);
          textNodes.forEach(function(node) {
            var text = node.textContent;
            var lowerText = text.toLowerCase();
            var lowerQuery = query.toLowerCase();
            var idx = lowerText.indexOf(lowerQuery);
            if (idx === -1) return;
            var fragment = document.createDocumentFragment();
            var lastIdx = 0;
            while (idx !== -1) {
              if (idx > lastIdx) {
                fragment.appendChild(document.createTextNode(text.substring(lastIdx, idx)));
              }
              var mark = document.createElement('mark');
              mark.className = 'search-match';
              mark.textContent = text.substring(idx, idx + query.length);
              fragment.appendChild(mark);
              lastIdx = idx + query.length;
              idx = lowerText.indexOf(lowerQuery, lastIdx);
            }
            if (lastIdx < text.length) {
              fragment.appendChild(document.createTextNode(text.substring(lastIdx)));
            }
            node.parentNode.replaceChild(fragment, node);
          });
        });
        matches = Array.from(document.querySelectorAll('mark.search-match'));
        if (matches.length > 0) {
          currentMatch = 0;
          activateMatch();
        }
        updateInfo();
      }
      function activateMatch() {
        document.querySelectorAll('mark.search-match-active').forEach(function(m) {
          m.className = 'search-match';
        });
        if (matches[currentMatch]) {
          matches[currentMatch].className = 'search-match-active';
          matches[currentMatch].scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }
      function updateInfo() {
        if (matches.length === 0) {
          info.textContent = '0 / 0';
        } else {
          info.textContent = (currentMatch + 1) + ' / ' + matches.length;
        }
      }
      function navigate(dir) {
        if (matches.length === 0) return;
        if (dir === 'next') {
          currentMatch = (currentMatch + 1) % matches.length;
        } else {
          currentMatch = (currentMatch - 1 + matches.length) % matches.length;
        }
        activateMatch();
        updateInfo();
      }
      function openSearch() {
        overlay.classList.remove('hidden');
        input.value = '';
        input.focus();
      }
      function closeSearch() {
        overlay.classList.add('hidden');
        clearHighlights();
        info.textContent = '0 / 0';
        input.value = '';
      }
      var debounceTimer = null;
      input.addEventListener('input', function() {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(function() {
          highlightText(input.value);
        }, 250);
      });
      input.addEventListener('keydown', function(e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          navigate(e.shiftKey ? 'prev' : 'next');
        } else if (e.key === 'Escape') {
          closeSearch();
        }
      });
      prevBtn.addEventListener('click', function() { navigate('prev'); });
      nextBtn.addEventListener('click', function() { navigate('next'); });
      closeBtn.addEventListener('click', closeSearch);
      self._handleKeyDown = function(e) {
        if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'F') {
          e.preventDefault();
          if (overlay.classList.contains('hidden')) {
            openSearch();
          } else {
            closeSearch();
          }
        }
      };
      document.addEventListener('keydown', self._handleKeyDown);
      self._overlay = overlay;
      self._closeSearch = closeSearch;
      self._debounceTimer = debounceTimer;
      ctx.logger.info('Card Search Highlight loaded (Ctrl+Shift+F)');
    },
    teardown: async function(ctx) {
      if (this._closeSearch) this._closeSearch();
      if (this._handleKeyDown) {
        document.removeEventListener('keydown', this._handleKeyDown);
      }
      if (this._debounceTimer) clearTimeout(this._debounceTimer);
      if (this._overlay && this._overlay.parentNode) {
        this._overlay.remove();
      }
      var marks = document.querySelectorAll('mark.search-match, mark.search-match-active');
      marks.forEach(function(m) {
        var parent = m.parentNode;
        parent.replaceChild(document.createTextNode(m.textContent), m);
        parent.normalize();
      });
      ctx.logger.info('Card Search Highlight disabled');
    }
  });
})();
